(function () {
  function tick() {
    document.querySelectorAll("[hx-get]").forEach(function (node) {
      var trigger = node.getAttribute("hx-trigger") || "";
      if (trigger.indexOf("every") === -1) return;
      fetch(node.getAttribute("hx-get"), { credentials: "same-origin" })
        .then(function (response) { return response.text(); })
        .then(function (html) { node.outerHTML = html; });
    });
  }
  setInterval(tick, 2000);
})();
